+                      padding: 20,
+                      minHeight: 120,
+                      display: 'flex',
+                      flexDirection: 'column',
+                      justifyContent: 'center',
+                      alignItems: 'center',
+                      textAlign: 'center',
+                      gap: 8,
+                    }}
