+                    <input ref={fileInputRef} accept={accept} type="file" onChange={onChoose} style={{ display: 'none' }} />
+                    <button
+                      type="button"
+                      aria-label="选择文件"
+                      onClick={() => fileInputRef.current?.click()}
+                      style={{
+                        width: 44,
